// The record catalogue: licence-checked, quality-checked tracks from the Free Music Archive, grouped into records.
// Generated by scripts/build-catalog.mjs from audio/licenses/fma-tracks.json - do not edit catalog.json by hand.
import catalog from './catalog.json'

export type Track = { id: string; title: string; src: string; duration: number; start: number; gainDb: number
  sourceUrl?: string } // the track's own FMA page (CC attribution: source)
export type Album = {
  id: string
  title: string
  artist: string
  cover: string // 1024 px album art (the real release artwork)
  dominant: string
  accent: string // album-reactive player accent
  duration: number // whole side: tracks + 2 s bands between them
  tracks: Track[]
  licence: string
  licenceUrl: string
  attributionRequired: boolean
  sourceUrl: string
  artistUrl: string
  source?: 'fma' | 'local' // local = imported from the listener's own files (kept in this browser)
  coverCredit?: string // set when the sleeve is a JazzTor design (the release has no published artwork)
}

/** Live list: the licensed catalogue plus records imported from local files (see data/localLibrary.ts). */
export const ALBUMS: Album[] = (catalog.records as Album[]).map((a) => ({ ...a, source: 'fma' as const }))
export const albumById = (id: string) => ALBUMS.find((a) => a.id === id) ?? ALBUMS[0]

/** Track playing at side-time t (seconds from the lead-in), and the offset inside it. */
export function trackAt(a: Album, t: number): { track: Track; index: number; offset: number } {
  let index = 0
  for (let i = 0; i < a.tracks.length; i++) if (t >= a.tracks[i].start) index = i
  const track = a.tracks[index]
  return { track, index, offset: Math.max(0, Math.min(track.duration, t - track.start)) }
}

/** CC attribution line (TASL: title, author, source, licence). */
export const creditLine = (a: Album, t?: Track) =>
  `“${t?.title ?? a.title}” by ${a.artist} · ${a.licence} · Free Music Archive`
